482	            BigDecimal unitPrice, boolean taxExempt, BigDecimal discountPct) {
483	        item.update(description, qty, unit, unitPrice, taxExempt, discountPct);
484	        recalculateAmount();
485	    }
486	
487	    /** Removes a line from this invoice and reworks its amount to no longer include what the line charged. */
488	    public void removeLineItem(InvoiceLineItem item) {
489	        lineItems.remove(item);
490	        recalculateAmount();
491	    }
492	
493	    /** The line on this invoice with the given id, if there is one. */
494	    public Optional<InvoiceLineItem> findLineItem(Long lineItemId) {
495	        return lineItems.stream().filter(l -> l.getId().equals(lineItemId)).findFirst();
496	    }
497	
498	    /** Replaces this invoice's discounts with a single percentage and reworks its amount to match. */
499	    public void applyDiscount(BigDecimal discountPct) {
500	        applyDiscount(discountPct, BigDecimal.ZERO);
501	    }
502	
503	    /**
504	     * Replaces this invoice's discounts with a single one, either a percentage or a flat amount (the other
505	     * being zero; zero for both leaves no discount), and reworks its amount to match.
506	     */
507	    public void applyDiscount(BigDecimal discountPct, BigDecimal discountAmount) {
508	        applyDiscount(discountPct, discountAmount, null);
509	    }
510	
511	    /**
512	     * Replaces this invoice's discounts with a single one, either a percentage (optionally capped at the
513	     * most it takes off) or a flat amount, and reworks its amount to match.
514	     */
515	    public void applyDiscount(BigDecimal discountPct, BigDecimal discountAmount, BigDecimal discountCap) {
516	        InvoiceDiscount discount = new InvoiceDiscount(this, discountPct, discountAmount, discountCap);
517	        discounts.clear();
518	        if (discountPct.signum() != 0 || discountAmount.signum() != 0) {
519	            discounts.add(discount);
520	        }
521	        recalculateAmount();
522	    }
523	
524	    /**
525	     * Adds another discount to this invoice, either a percentage or a flat amount (the other being zero),
526	     * and reworks its amount to match.
527	     */
528	    public InvoiceDiscount addDiscount(BigDecimal discountPct, BigDecimal discountAmount) {
529	        return addDiscount(discountPct, discountAmount, null);
530	    }
531	
532	    /**
533	     * Adds another discount to this invoice, either a percentage (optionally capped at the most it takes
534	     * off) or a flat amount, and reworks its amount to match.
535	     */
536	    public InvoiceDiscount addDiscount(BigDecimal discountPct, BigDecimal discountAmount, BigDecimal discountCap) {
537	        if (discountPct.signum() == 0 && discountAmount.signum() == 0) {
538	            throw new IllegalArgumentException("A discount takes off a percentage or a flat amount");
539	        }
540	        InvoiceDiscount discount = new InvoiceDiscount(this, discountPct, discountAmount, discountCap);
541	        discounts.add(discount);
542	        recalculateAmount();
543	        return discount;
544	    }
545	
546	    /** Removes a discount from this invoice and reworks its amount to match. */
547	    public void removeDiscount(InvoiceDiscount discount) {
548	        discounts.remove(discount);
549	        recalculateAmount();
550	    }
551	
552	    /** The discount on this invoice with the given id, if there is one. */
553	    public Optional<InvoiceDiscount> findDiscount(Long discountId) {
554	        return discounts.stream().filter(d -> d.getId().equals(discountId)).findFirst();
555	    }
556	
557	    /** Sets the sales tax percentage added to this invoice and reworks its amount to match. */
558	    public void applyTax(BigDecimal taxPct) {
559	        this.taxPct = taxPct.setScale(2, RoundingMode.HALF_UP);
560	        recalculateAmount();
561	    }
562	
563	    /** Sets whether this invoice's prices already include tax and reworks its amount to match. */
564	    public void applyTaxInclusive(boolean taxInclusive) {
565	        this.taxInclusive = taxInclusive;
566	        recalculateAmount();
567	    }
568	
569	    /** Sets whether this invoice is for a tax-exempt client and reworks its amount to match. */
570	    public void applyTaxExempt(boolean taxExempt) {
571	        this.taxExempt = taxExempt;
572	        recalculateAmount();
573	    }
574	
575	    /** Sets the levy (second tax) percentage added to this invoice and reworks its amount to match. */
576	    public void applyLevy(BigDecimal levyPct) {
577	        this.levyPct = levyPct.setScale(2, RoundingMode.HALF_UP);
578	        recalculateAmount();
579	    }
580	
581	    /** Sets the flat surcharge (such as a handling fee) added to this invoice and reworks its amount to match. */
582	    public void applySurcharge(BigDecimal surcharge) {
583	        this.surcharge = surcharge.setScale(2, RoundingMode.HALF_UP);
584	        recalculateAmount();
585	    }
586	
587	    /** Sets the minimum charge billed on this invoice and reworks its amount to match. */
588	    public void applyMinimumCharge(BigDecimal minimumCharge) {
589	        this.minimumCharge = minimumCharge.setScale(2, RoundingMode.HALF_UP);
590	        recalculateAmount();
591	    }
592	
593	    /** Sets the late fee charged for each day this invoice is overdue. It does not change the amount invoiced. */
594	    public void applyLateFee(BigDecimal lateFeePerDay) {
595	        this.lateFeePerDay = lateFeePerDay.setScale(2, RoundingMode.HALF_UP);
596	    }
597	
598	    public BigDecimal getLateFeePerDay() {
599	        return lateFeePerDay;
600	    }
601	
602	    /** Sets the interest charged for each day an instalment of this invoice is paid late. */
603	    public void applyInstalmentInterest(BigDecimal interestPerDay) {
604	        this.instalmentInterestPerDay = interestPerDay.setScale(2, RoundingMode.HALF_UP);
605	    }
606	
607	    public BigDecimal getInstalmentInterestPerDay() {
608	        return instalmentInterestPerDay;
609	    }
610	
611	    /** Sets the percentage of this invoice held back as retention. It does not change the amount invoiced. */
612	    public void applyRetention(BigDecimal retentionPct) {
613	        this.retentionPct = retentionPct.setScale(2, RoundingMode.HALF_UP);
614	    }
615	
616	    public BigDecimal getRetentionPct() {
617	        return retentionPct;
618	    }
619	
620	    /** Releases the retention held back, so it becomes due. The percentage is kept on record. */
621	    public void releaseRetention() {
622	        this.retentionReleased = true;
623	    }
624	
625	    public boolean isRetentionReleased() {
626	        return retentionReleased;
627	    }
628	
629	    /**
630	     * The amount held back as retention: the retention percentage of the amount invoiced, or nothing once
631	     * the retention has been released.
632	     */
633	    public BigDecimal getRetention() {
634	        return retentionReleased ? BigDecimal.ZERO.setScale(2) : percentOf(amount, retentionPct);
635	    }
636	
637	    /** What is due now: the amount invoiced less the retention held back. */
638	    public BigDecimal getDueNow() {
639	        return amount.subtract(getRetention());
640	    }
641	
642	    /**
643	     * How many days past its due date the invoice is on the given day; zero unless it has been sent and
644	     * is still owed (sent or part paid).
645	     */
646	    public long daysLate(InvoiceStatus status, LocalDate today) {
647	        if (status != InvoiceStatus.SENT && status != InvoiceStatus.PARTIAL) {
648	            return 0;
649	        }
650	        return Math.max(0, ChronoUnit.DAYS.between(dueDate, today));
651	    }
652	
653	    /** The late fee accrued by the given day: the fee per day times the days the invoice is overdue. */
654	    public BigDecimal lateFee(InvoiceStatus status, LocalDate today) {
655	        return lateFeePerDay.multiply(BigDecimal.valueOf(daysLate(status, today))).setScale(2, RoundingMode.HALF_UP);
656	    }
657	
658	    /**
659	     * Sets the early-payment discount offered on this invoice: the percentage taken off what is owed if it is
660	     * paid within its client's early-payment window. It does not change the amount owed.
661	     */
662	    public void applyEarlyPayment(BigDecimal earlyPaymentPct) {
663	        this.earlyPaymentPct = earlyPaymentPct.setScale(2, RoundingMode.HALF_UP);
664	    }
665	
666	    /**
667	     * Sets the settlement rebate offered on this invoice: the percentage of the amount given back if it is
668	     * paid before the due date. It does not change the amount invoiced.
669	     */
670	    public void applyRebate(BigDecimal rebatePct) {
671	        this.rebatePct = rebatePct.setScale(2, RoundingMode.HALF_UP);
672	    }
673	
674	    /**
675	     * The discount taken off one line, to the cent: the uncapped percentages together, plus its share of
676	     * what the flat amounts and the capped percentages take off in proportion to what the line charges
677	     * out of the subtotal.
678	     */
679	    private BigDecimal discountOn(BigDecimal line) {
680	        BigDecimal subtotal = getSubtotal();
681	        BigDecimal pct = percentOf(line, uncappedPct(subtotal));
682	        if (subtotal.signum() == 0) {
683	            return pct;
684	        }
685	        BigDecimal flatShare = sharedDiscount(subtotal).multiply(line).divide(subtotal, 2, RoundingMode.HALF_UP);
686	        return pct.add(flatShare);
687	    }
688	
689	    /** The percentages not limited by a cap, added up (never more than 100). */
690	    private BigDecimal uncappedPct(BigDecimal subtotal) {
691	        return discounts.stream().filter(d -> d.isPercentage() && !isCappedAt(subtotal, d)).map(InvoiceDiscount::getDiscountPct)
692	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add).min(BigDecimal.valueOf(100).setScale(2));
693	    }
694	
695	    /**
696	     * What the flat discounts and the capped percentages actually take off the subtotal together, shared
697	     * across the lines in proportion to what each charges.
698	     */
699	    private BigDecimal sharedDiscount(BigDecimal subtotal) {
700	        return discounts.stream().filter(d -> !d.isPercentage() || isCappedAt(subtotal, d)).map(this::discountTakenBy)
701	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
702	    }
703	
704	    /** The sales tax on one discounted taxable line (or inside it, when tax-inclusive), to the cent. */
705	    private BigDecimal taxOn(BigDecimal line) {
706	        return taxInclusive ? includedIn(line, taxPct) : percentOf(line, taxPct);
707	    }
708	
709	    /** The levy on one discounted taxable line (or inside it, when tax-inclusive), to the cent. */
710	    private BigDecimal levyOn(BigDecimal line) {
711	        return taxInclusive ? includedIn(line, levyPct) : percentOf(line, levyPct);
712	    }
713	
714	    private static BigDecimal percentOf(BigDecimal base, BigDecimal pct) {
715	        return base.multiply(pct).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_UP);
716	    }
717	
718	    private void recalculateAmount() {
719	        this.amount = getNetTotal().max(minimumCharge);
720	    }
721	
722	    /** Marks this invoice as sent to the client. */
723	    public void markSent() {
724	        this.status = InvoiceStatus.SENT;
725	    }
726	
727	    /** Cancels this invoice, so it is no longer owed. */
728	    public void markVoid() {
729	        this.status = InvoiceStatus.VOID;
730	    }
731	
732	    /** Flags this invoice as disputed by the client; it still counts as owed. */
733	    public void markDisputed() {
734	        this.disputed = true;
735	    }
736	
737	    public boolean isDisputed() {
738	        return disputed;
739	    }
740	
741	    /** Writes this invoice off as bad debt, so it is no longer owed. */
742	    public void markWrittenOff() {
743	        this.status = InvoiceStatus.WRITTEN_OFF;
744	    }
745	
746	    /** Writes part of this invoice off as bad debt, so that part is no longer owed while the rest still is. */
747	    public void writeOffPart(BigDecimal part) {
748	        this.writeOffAmount = writeOffAmount.add(part).setScale(2, RoundingMode.HALF_UP);
749	    }
750	
751	    public BigDecimal getWriteOffAmount() {
752	        return writeOffAmount;
753	    }
754	
755	    public String getPoNumber() {
756	        return poNumber;
757	    }
758	
759	    public void setPoNumber(String poNumber) {
760	        this.poNumber = poNumber;
761	    }
762	
763	    /**
764	     * What is left to pay on this invoice given the totals paid and credited against it, less any part written
765	     * off and any settlement rebate earned; nothing once it is void or written off.
766	     */
767	    public BigDecimal amountDue(BigDecimal paid, BigDecimal credited) {
768	        return status.isClosedUnpaid() ? BigDecimal.ZERO.setScale(2)
769	                : amount.subtract(paid).subtract(credited).subtract(writeOffAmount).subtract(rebateTaken);
770	    }
771	
772	    /**
773	     * What the client owes on this invoice right now given the totals paid and credited against it: what is
774	     * left to pay less the retention still held back, never below nothing on account of the retention.
775	     */
776	    public BigDecimal dueNow(BigDecimal paid, BigDecimal credited) {
777	        BigDecimal left = amountDue(paid, credited);
778	        if (left.signum() <= 0 || status.isClosedUnpaid()) {
779	            return left;
780	        }
781	        return left.subtract(getRetention()).max(BigDecimal.ZERO.setScale(2));
782	    }
783	
784	    /**
785	     * This invoice's status given the totals paid and credited against it. Once sent, it is PAID when the
786	     * payments, credit notes, any part written off and any settlement rebate earned together clear the amount, PARTIAL once something has been
787	     * paid, credited or written off, otherwise still SENT. Drafts, void and written-off invoices keep their status, as does one marked paid by hand.
788	     */
789	    public InvoiceStatus statusFor(BigDecimal paid, BigDecimal credited) {
790	        if (status == InvoiceStatus.DRAFT || status.isClosedUnpaid()) {
791	            return status;
792	        }
793	        BigDecimal settled = paid.add(credited).add(writeOffAmount).add(rebateTaken);
794	        if (settled.compareTo(amount) >= 0 || (status == InvoiceStatus.PAID && settled.signum() == 0)) {
795	            return InvoiceStatus.PAID;
796	        }
797	        return settled.signum() > 0 ? InvoiceStatus.PARTIAL : InvoiceStatus.SENT;
798	    }
799	
800	    /**
801	     * Works out this sent invoice's status from what is still owed on it after the totals paid and credited against
802	     * it and any part written off: PAID once nothing is left, PARTIAL once something has been settled, otherwise
803	     * still SENT.
804	     */
805	    public void applySettledTotals(BigDecimal paid, BigDecimal credited) {
806	        if (status == InvoiceStatus.DRAFT || status.isClosedUnpaid()) {
807	            throw new IllegalStateException("A " + status.name().toLowerCase() + " invoice cannot be settled");
808	        }
809	        this.status = statusFor(paid, credited);
810	    }
811	}
