82	        List<Invoice> found = invoices.findByProjectIdOrderById(projectId);
83	        Map<Long, BigDecimal> paid = paidByInvoice(found);
84	        Map<Long, BigDecimal> credited = creditedByInvoice(found);
85	        Map<Long, List<Instalment>> schedules = instalments
86	                .findByInvoiceIdIn(found.stream().map(Invoice::getId).toList()).stream()
87	                .collect(Collectors.groupingBy(Instalment::getInvoiceId));
88	        LocalDate today = LocalDate.now(clock);
89	        return found.stream()
90	                .map(i -> {
91	                    BigDecimal invoicePaid = paid.getOrDefault(i.getId(), BigDecimal.ZERO);
92	                    BigDecimal invoiceCredited = credited.getOrDefault(i.getId(), BigDecimal.ZERO);
93	                    ScheduleStatus schedule = scheduleStatus(i.statusFor(invoicePaid, invoiceCredited),
94	                            schedules.getOrDefault(i.getId(), List.of()), today);
95	                    return InvoiceResponse.from(i, invoicePaid, invoiceCredited, schedule);
96	                })
97	                .toList();
98	    }
