100	    /**
101	     * How an invoice is keeping to its instalment plan: only an owing invoice with instalments has one. It is BEHIND
102	     * once an unpaid instalment is past its due date, otherwise ON_TRACK.
103	     */
104	    private static ScheduleStatus scheduleStatus(InvoiceStatus status, List<Instalment> schedule, LocalDate today) {
105	        if (!status.isOwing() || schedule.isEmpty()) {
106	            return null;
107	        }
108	        boolean overdue = schedule.stream().anyMatch(n -> !n.isPaid() && n.getDueDate().isBefore(today));
109	        return overdue ? ScheduleStatus.BEHIND : ScheduleStatus.ON_TRACK;
110	    }
