150	    /**
151	     * A client's statement for the given date range (both ends included): the balance owed at the start of it, the
152	     * entries dated within it in date order each carrying the running balance, and the balance owed at its end.
153	     */
154	    @Transactional(readOnly = true)
155	    public ClientStatementRangeResponse statementForRange(Long clientId, LocalDate from, LocalDate to) {
156	        if (to.isBefore(from)) {
157	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The range must end on or after its start");
158	        }
159	        Client client = clients.findById(clientId)
160	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown client"));
161	        List<StatementEntry> dated = accountEntries(clientId, invoices.findByClientIdWithProject(clientId)).stream()
162	                .filter(e -> e.date() != null)
163	                .sorted(StatementEntry.DATE_ORDER)
164	                .toList();
165	        BigDecimal opening = dated.stream()
166	                .filter(e -> e.date().isBefore(from))
167	                .map(StatementEntry::change)
168	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
169	        BigDecimal balance = opening;
170	        List<StatementEntry> within = new ArrayList<>();
171	        for (StatementEntry entry : dated) {
172	            if (!entry.date().isBefore(from) && !entry.date().isAfter(to)) {
173	                balance = balance.add(entry.change());
174	                within.add(entry.withBalance(balance));
175	            }
176	        }
177	        return new ClientStatementRangeResponse(client.getId(), client.getCurrency(), from, to, opening, within, balance);
178	    }
