180	    /**
181	     * How old a client's debt is as at today: what is left to pay on each owed invoice (not a draft, void or written
182	     * off) counted against how many days past its due date it is.
183	     */
184	    @Transactional(readOnly = true)
185	    public ClientAgingResponse agingForClient(Long clientId) {
186	        Client client = clients.findById(clientId)
187	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown client"));
188	        LocalDate today = LocalDate.now(clock);
189	        List<Invoice> found = invoices.findByClientIdWithProject(clientId);
190	        Map<Long, BigDecimal> paid = paidByInvoice(found);
191	        Map<Long, BigDecimal> credited = creditedByInvoice(found);
192	        BigDecimal current = BigDecimal.ZERO.setScale(2);
193	        BigDecimal days30To60 = BigDecimal.ZERO.setScale(2);
194	        BigDecimal days60Plus = BigDecimal.ZERO.setScale(2);
195	        for (Invoice invoice : found) {
196	            BigDecimal invoicePaid = paid.getOrDefault(invoice.getId(), BigDecimal.ZERO);
197	            BigDecimal invoiceCredited = credited.getOrDefault(invoice.getId(), BigDecimal.ZERO);
198	            InvoiceStatus status = invoice.statusFor(invoicePaid, invoiceCredited);
199	            if (status == InvoiceStatus.DRAFT || status.isClosedUnpaid()) {
200	                continue;
201	            }
202	            BigDecimal due = invoice.amountDue(invoicePaid, invoiceCredited);
203	            if (due.signum() <= 0) {
204	                continue;
205	            }
206	            long overdue = invoice.getDueDate() == null ? 0
207	                    : ChronoUnit.DAYS.between(invoice.getDueDate(), today);
208	            if (overdue > 60) {
209	                days60Plus = days60Plus.add(due);
210	            } else if (overdue > 30) {
211	                days30To60 = days30To60.add(due);
212	            } else {
213	                current = current.add(due);
214	            }
215	        }
216	        return new ClientAgingResponse(client.getId(), client.getCurrency(), today,
217	                current.setScale(2, RoundingMode.HALF_UP), days30To60.setScale(2, RoundingMode.HALF_UP),
218	                days60Plus.setScale(2, RoundingMode.HALF_UP));
219	    }
