221	    /**
222	     * The entries on a client's running account. Drafts have not been sent and void invoices were cancelled, so
223	     * neither is charged. A payment made out of held deposits is left out, as the deposit was already credited
224	     * when it was paid in.
225	     */
226	    private List<StatementEntry> accountEntries(Long clientId, List<Invoice> found) {
227	        List<StatementEntry> entries = new ArrayList<>();
228	        List<Long> sent = new ArrayList<>();
229	        Map<Long, String> poNumbers = new HashMap<>();
230	        for (Invoice invoice : found) {
231	            if (invoice.getStatus() == InvoiceStatus.DRAFT) {
232	                continue;
233	            }
234	            sent.add(invoice.getId());
235	            if (invoice.getPoNumber() != null) {
236	                poNumbers.put(invoice.getId(), invoice.getPoNumber());
237	            }
238	            if (invoice.getStatus() != InvoiceStatus.VOID) {
239	                entries.add(StatementEntry.charge(StatementEntry.Kind.INVOICE, invoice.getId(), invoice.getId(),
240	                        invoice.getIssuedDate(), "Invoice #" + invoice.getId(), invoice.getAmount(),
241	                        invoice.getPoNumber()));
242	            }
243	        }
244	        if (!sent.isEmpty()) {
245	            for (Payment payment : payments.findByInvoiceIdIn(sent)) {
246	                if (payment.getDepositApplicationId() == null) {
247	                    entries.add(StatementEntry.credit(StatementEntry.Kind.PAYMENT, payment.getId(), payment.getInvoiceId(),
248	                            payment.getDate(), "Payment on invoice #" + payment.getInvoiceId(), payment.getAmount(),
249	                            poNumbers.get(payment.getInvoiceId())));
250	                }
251	            }
252	            for (CreditNote note : creditNotes.findByInvoiceIdIn(sent)) {
253	                entries.add(StatementEntry.credit(StatementEntry.Kind.CREDIT_NOTE, note.getId(), note.getInvoiceId(),
254	                        LocalDate.ofInstant(note.getIssuedAt(), ZoneOffset.UTC),
255	                        "Credit note on invoice #" + note.getInvoiceId(), note.getAmount(),
256	                        poNumbers.get(note.getInvoiceId())));
257	            }
258	        }
259	        for (Deposit deposit : deposits.findByClientIdOrderByDateAscIdAsc(clientId)) {
260	            entries.add(StatementEntry.credit(StatementEntry.Kind.DEPOSIT, deposit.getId(), null, deposit.getDate(),
261	                    "Deposit", deposit.getAmount(), null));
262	        }
263	        for (Refund refund : refunds.findByClientIdOrderByDateDescIdDesc(clientId)) {
264	            entries.add(StatementEntry.charge(StatementEntry.Kind.REFUND, refund.getId(), null, refund.getDate(),
265	                    "Refund", refund.getAmount(), null));
266	        }
267	        return entries;
268	    }
