296	    @Transactional
297	    public InvoiceResponse create(Long projectId, InvoiceRequest request) {
298	        Project project = projects.findById(projectId)
299	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown job"));
300	        if (project.isClosed()) {
301	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The job is closed; no new invoice can be raised on it");
302	        }
303	        LocalDate issued = request.issuedDate() != null ? request.issuedDate() : LocalDate.now();
304	        // Without a due date the invoice falls due after the client's payment terms (net N days).
305	        LocalDate due = request.dueDate() != null ? request.dueDate()
306	                : issued.plusDays(InvoiceRequest.termDays(project.getClient().getPaymentTermsDays()));
307	        if (due.isBefore(issued)) {
308	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Due date must not be before the issue date");
309	        }
310	        Invoice invoice = new Invoice(project, issued, due);
311	        if (request.amount() != null) {
312	            invoice.addLineItem(InvoiceRequest.SINGLE_AMOUNT_DESCRIPTION, BigDecimal.ONE, null, request.amount());
313	        }
314	        invoice.applyTax(request.taxPct() != null ? request.taxPct() : settings.defaultTaxPct());
315	        // A new invoice starts with the client's standard discount, if they have one.
316	        BigDecimal defaultDiscountPct = project.getClient().getDefaultDiscountPct();
317	        if (defaultDiscountPct.signum() > 0) {
318	            invoice.addDiscount(defaultDiscountPct, BigDecimal.ZERO);
319	        }
320	        Invoice saved = invoices.save(invoice);
321	        return InvoiceResponse.from(saved, BigDecimal.ZERO, BigDecimal.ZERO);
322	    }
