503	     * Sends a draft invoice and records the sending in the audit log. An invoice that would take the
504	     * client over their credit limit is refused and stays a draft.
505	     */
506	    @Transactional
507	    public InvoiceResponse send(Long projectId, Long invoiceId) {
508	        Invoice invoice = find(projectId, invoiceId);
509	        if (invoice.getStatus() != InvoiceStatus.DRAFT) {
510	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a draft invoice can be sent");
511	        }
512	        if (invoice.getAmount().signum() == 0) {
513	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Add a line item before sending the invoice");
514	        }
515	        Client client = invoice.getProject().getClient();
516	        BigDecimal limit = client.getCreditLimit();
517	        if (limit != null && clientService.outstanding(client.getId()).add(invoice.getAmount()).compareTo(limit) > 0) {
518	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
519	                    "Sending this invoice would take the client over their credit limit");
520	        }
521	        invoice.markSent();
522	        invoices.flush();
523	        audit.record("INVOICE_SENT id=" + invoice.getId() + " amount=" + invoice.getAmount().toPlainString());
524	        return toResponse(invoice);
525	    }
