527	    /**
528	     * Sends every draft invoice on a job in one go, and records each sending in the audit log. It is all or
529	     * nothing: if any draft has no line items, or sending them all would take the client over their credit
530	     * limit, none are sent.
531	     */
532	    @Transactional
533	    public List<InvoiceResponse> sendDrafts(Long projectId) {
534	        if (!projects.existsById(projectId)) {
535	            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown job");
536	        }
537	        List<Invoice> drafts = invoices.findByProjectIdOrderById(projectId).stream()
538	                .filter(i -> i.getStatus() == InvoiceStatus.DRAFT)
539	                .toList();
540	        if (drafts.isEmpty()) {
541	            throw new ResponseStatusException(HttpStatus.CONFLICT, "There are no draft invoices to send");
542	        }
543	        if (drafts.stream().anyMatch(i -> i.getAmount().signum() == 0)) {
544	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Add a line item to every draft before sending");
545	        }
546	        Client client = drafts.get(0).getProject().getClient();
547	        BigDecimal limit = client.getCreditLimit();
548	        BigDecimal total = drafts.stream().map(Invoice::getAmount).reduce(BigDecimal.ZERO, BigDecimal::add);
549	        if (limit != null && clientService.outstanding(client.getId()).add(total).compareTo(limit) > 0) {
550	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
551	                    "Sending these invoices would take the client over their credit limit");
552	        }
553	        drafts.forEach(Invoice::markSent);
554	        invoices.flush();
555	        drafts.forEach(i -> audit.record("INVOICE_SENT id=" + i.getId() + " amount=" + i.getAmount().toPlainString()));
556	        return drafts.stream().map(this::toResponse).toList();
557	    }
