563	    @Transactional
564	    public InvoiceResponse cancel(Long projectId, Long invoiceId) {
565	        Invoice invoice = find(projectId, invoiceId);
566	        if (invoice.getStatus() != InvoiceStatus.SENT) {
567	            throw new ResponseStatusException(HttpStatus.CONFLICT,
568	                    "Only a sent invoice with no payments recorded can be cancelled");
569	        }
570	        invoice.markVoid();
571	        invoices.flush();
572	        audit.record("INVOICE_VOIDED id=" + invoice.getId() + " amount=" + invoice.getAmount().toPlainString());
573	        return toResponse(invoice);
574	    }
575	
576	    /**
577	     * Flags a sent or part-paid invoice as disputed by the client and records it in the audit log. The invoice still
578	     * counts as owed; the flag only marks it.
579	     */
580	    @Transactional
581	    public InvoiceResponse dispute(Long projectId, Long invoiceId) {
582	        Invoice invoice = find(projectId, invoiceId);
583	        if (!invoice.getStatus().isOwing()) {
584	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only an owing invoice can be disputed");
585	        }
586	        if (!invoice.isDisputed()) {
587	            invoice.markDisputed();
588	            invoices.flush();
589	            audit.record("INVOICE_DISPUTED id=" + invoice.getId());
590	        }
591	        return toResponse(invoice);
592	    }
593	
594	    /**
595	     * Writes off a sent or part-paid invoice as bad debt, so what is left on it no longer counts toward what is
596	     * owed while the invoice stays on record, and records the write-off (the balance given up) in the audit log.
597	     */
598	    @Transactional
599	    public InvoiceDetailResponse writeOff(Long projectId, Long invoiceId) {
600	        Invoice invoice = find(projectId, invoiceId);
601	        BigDecimal paid = payments.sumAmountByInvoiceId(invoiceId);
602	        BigDecimal credited = creditNotes.sumAmountByInvoiceId(invoiceId);
603	        if (!invoice.statusFor(paid, credited).isOwing()) {
604	            throw new ResponseStatusException(HttpStatus.CONFLICT,
605	                    "Only a sent invoice with something still owed can be written off");
606	        }
607	        BigDecimal balance = invoice.amountDue(paid, credited);
608	        invoice.markWrittenOff();
609	        invoices.flush();
610	        audit.record("INVOICE_WRITTEN_OFF id=" + invoice.getId() + " amount=" + balance.setScale(2).toPlainString());
611	        return detail(invoice);
612	    }
613	
614	    /**
615	     * Writes off part of a sent or part-paid invoice as bad debt, so that part no longer counts toward what is
616	     * owed while the rest still does, and records the part given up in the audit log. The invoice's status is then
617	     * worked out from what is still owed after the write-off. Writing off everything still owed writes off the
618	     * whole invoice.
619	     */
620	    @Transactional
621	    public InvoiceDetailResponse writeOffPart(Long projectId, Long invoiceId, PartialWriteOffRequest request) {
622	        Invoice invoice = find(projectId, invoiceId);
623	        BigDecimal paid = payments.sumAmountByInvoiceId(invoiceId);
624	        BigDecimal credited = creditNotes.sumAmountByInvoiceId(invoiceId);
625	        if (!invoice.statusFor(paid, credited).isOwing()) {
626	            throw new ResponseStatusException(HttpStatus.CONFLICT,
627	                    "Only a sent invoice with something still owed can be written off");
628	        }
629	        BigDecimal balance = invoice.amountDue(paid, credited);
630	        int comparison = request.amount().compareTo(balance);
631	        if (comparison > 0) {
632	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
633	                    "Cannot write off more than is still owed");
634	        }
635	        if (comparison == 0) {
636	            return writeOff(projectId, invoiceId);
637	        }
638	        invoice.writeOffPart(request.amount());
639	        invoice.applySettledTotals(paid, credited);
640	        invoices.flush();
641	        audit.record("INVOICE_PART_WRITTEN_OFF id=" + invoice.getId() + " amount="
642	                + request.amount().setScale(2).toPlainString());
643	        return detail(invoice);
644	    }
645	
646	    private InvoiceResponse toResponse(Invoice invoice) {
647	        return InvoiceResponse.from(invoice, payments.sumAmountByInvoiceId(invoice.getId()),
648	                creditNotes.sumAmountByInvoiceId(invoice.getId()));
649	    }
650	
651	    private Invoice find(Long projectId, Long invoiceId) {
652	        return invoices.findById(invoiceId)
653	                .filter(i -> i.getProject().getId().equals(projectId))
654	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown invoice"));
655	    }
656	
657	    private Invoice findDraft(Long projectId, Long invoiceId) {
658	        Invoice invoice = find(projectId, invoiceId);
659	        if (invoice.getStatus() != InvoiceStatus.DRAFT) {
660	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a draft invoice can be changed");
661	        }
662	        return invoice;
663	    }
664	
665	    private static InvoiceLineItem findLineItem(Invoice invoice, Long lineItemId) {
666	        return invoice.findLineItem(lineItemId)
667	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown line item"));
668	    }
669	
670	    private InvoiceDetailResponse detail(Invoice invoice) {
671	        return detail(invoice, invoice.getStatus());
672	    }
673	
674	    /**
675	     * The invoice in full; a foreign invoice also converted into the home currency at the exchange rate
676	     * from its issue date, so a later rate never changes what it was worth.
677	     */
678	    private InvoiceDetailResponse detail(Invoice invoice, InvoiceStatus status) {
679	        String home = settings.homeCurrency();
680	        String currency = invoice.getCurrency();
681	        BigDecimal homeAmount = currency.equals(home) ? null
682	                : fxRates.toHome(currency, invoice.getIssuedDate(), invoice.getAmount()).orElse(null);
683	        BigDecimal amountDue = invoice.dueNow(payments.sumAmountByInvoiceId(invoice.getId()),
684	                creditNotes.sumAmountByInvoiceId(invoice.getId()));
685	        BigDecimal fxGainLoss = currency.equals(home) ? null : fxGainLoss(invoice, currency);
686	        return InvoiceDetailResponse.from(invoice, status, home, homeAmount, LocalDate.now(clock), amountDue, fxGainLoss);
687	    }
688	
689	    /**
690	     * The exchange gain (positive) or loss (negative) in the home currency realised by the payments on a foreign
691	     * invoice: each payment's amount is worth its value at the rate on the payment's date less its value at the
692	     * rate on the invoice's issue date. Null when there are no payments or a rate is missing.
693	     */
694	    private BigDecimal fxGainLoss(Invoice invoice, String currency) {
695	        List<Payment> paid = payments.findByInvoiceIdOrderByDateAscIdAsc(invoice.getId());
696	        if (paid.isEmpty() || invoice.getIssuedDate() == null) {
697	            return null;
698	        }
699	        BigDecimal total = BigDecimal.ZERO;
700	        for (Payment payment : paid) {
701	            Optional<BigDecimal> atIssue = fxRates.toHome(currency, invoice.getIssuedDate(), payment.getAmount());
702	            Optional<BigDecimal> atPayment = fxRates.toHome(currency, payment.getDate(), payment.getAmount());
703	            if (atIssue.isEmpty() || atPayment.isEmpty()) {
704	                return null;
705	            }
706	            total = total.add(atPayment.get().subtract(atIssue.get()));
707	        }
708	        return total;
709	    }
710	}
